import os
import re


def task_func(pattern: str, replacement: str, directory: str) -> bool:
    try:
        if not os.path.isdir(directory):
            return False

        regex = re.compile(pattern)
        entries = os.listdir(directory)

        # Collect rename operations for regular files only.
        renames = []
        source_names = set()
        target_names = {}

        for name in entries:
            src = os.path.join(directory, name)
            if not os.path.isfile(src):
                continue

            if not regex.search(name):
                continue

            new_name = regex.sub(replacement, name)
            if new_name == name:
                continue

            # Keep the renamed file inside the same directory.
            if (
                not new_name
                or new_name in {".", ".."}
                or os.path.basename(new_name) != new_name
            ):
                return False

            if new_name in target_names and target_names[new_name] != name:
                return False

            source_names.add(name)
            target_names[new_name] = name
            renames.append((name, new_name))

        if not renames:
            return True

        # Ensure there are no conflicts with unrelated existing files.
        for _, new_name in renames:
            dst = os.path.join(directory, new_name)
            if os.path.exists(dst) and new_name not in source_names:
                return False

        # Two-phase rename to safely handle cycles and swaps.
        temp_moves = []
        finalized = []

        try:
            for i, (old_name, new_name) in enumerate(renames):
                src = os.path.join(directory, old_name)
                temp_name = f".__rename_tmp__{os.getpid()}_{i}__{old_name}"
                temp_path = os.path.join(directory, temp_name)
                while os.path.exists(temp_path):
                    temp_name += "_x"
                    temp_path = os.path.join(directory, temp_name)

                os.replace(src, temp_path)
                temp_moves.append((temp_path, src, os.path.join(directory, new_name)))

            for temp_path, src, dst in temp_moves:
                os.replace(temp_path, dst)
                finalized.append((dst, temp_path))

            return True

        except Exception:
            # Best-effort rollback of any completed final renames.
            for dst, temp_path in reversed(finalized):
                try:
                    os.replace(dst, temp_path)
                except Exception:
                    pass

            # Restore any remaining temporary files to their original names.
            for temp_path, src, _ in reversed(temp_moves):
                if os.path.exists(temp_path):
                    try:
                        os.replace(temp_path, src)
                    except Exception:
                        pass

            return False

    except Exception:
        return False
